mapper.select:
WHERE pos.pos_status = 1 AND cmp.cmp_status = 1
AND pos.pos_company_id = #{query.companyId}
AND ( pos.pos_title LIKE CONCAT('%', #{query.keyword}, '%') OR cmp.cmp_name LIKE CONCAT('%', #{query.keyword}, '%') OR pos.pos_work_city LIKE CONCAT('%', #{query.keyword}, '%') OR pos.pos_department LIKE CONCAT('%', #{query.keyword}, '%') OR EXISTS ( SELECT 1 FROM t_pos_skill search_skill WHERE search_skill.psk_position_id = pos.pos_id AND search_skill.psk_name LIKE CONCAT('%', #{query.keyword}, '%') ) )
AND pos.pos_department = #{query.category}
AND pos.pos_work_city LIKE CONCAT('%', #{query.city}, '%')
AND pos.pos_work_city LIKE CONCAT('%', #{query.district}, '%')
AND ( CAST(pos.pos_job_type AS CHAR) = #{query.employmentType} OR (#{query.employmentType} = 'FULL_TIME' AND pos.pos_job_type = 1) OR (#{query.employmentType} = 'INTERNSHIP' AND pos.pos_job_type = 2) OR (#{query.employmentType} = 'PART_TIME' AND pos.pos_job_type = 3) )
AND (pos.pos_salary_max IS NULL OR pos.pos_salary_max >= #{query.salaryMin})
AND (pos.pos_salary_min IS NULL OR pos.pos_salary_min <= #{query.salaryMax})
AND pos.pos_experience_required = #{query.experienceMin}
AND pos.pos_education_required = #{query.education}
AND cmp.cmp_industry LIKE CONCAT('%', #{query.industry}, '%')
AND cmp.cmp_size = #{query.companySize}
ORDER BY pos.pos_salary_max DESC, pos.pos_created_at DESC ORDER BY COALESCE(match_score, 0) DESC, pos.pos_created_at DESC ORDER BY pos.pos_created_at DESC, pos.pos_id DESC


WHERE pos.pos_id = #{jobId}
  AND pos.pos_status IN (1, 2)
  AND cmp.cmp_status = 1
